import{_ as e}from"./chunks/07-security-guard.Ddic_NEM.js";import{_ as r,o,c as a,a2 as d}from"./chunks/framework.BauHmMU1.js";const m=JSON.parse('{"title":"第七幕 · 黑客来敲门","description":"","frontmatter":{},"headers":[],"relativePath":"comics/07-security-guard.md","filePath":"comics/07-security-guard.md","lastUpdated":1792595797000}'),c={name:"comics/07-security-guard.md"};function s(i,t,n,l,h,u){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="第七幕-·-黑客来敲门" tabindex="-1">第七幕 · 黑客来敲门 <a class="header-anchor" href="#第七幕-·-黑客来敲门" aria-label="Permalink to &quot;第七幕 · 黑客来敲门&quot;">​</a></h1><p><img src="'+e+'" alt="CSWSH 攻击与六道安全防线"></p><blockquote><p>对应主线教程：<a href="./../07-security">第 7 章 WebSocket 安全机制</a>（含 7.9 RFC 6455 规范解读） 配套代码：<a href="../examples/node/secure-server.js">secure-server.js</a>、<a href="../examples/node/security-test.js">security-test.js</a></p></blockquote><h2 id="cswsh-跨站-websocket-劫持" tabindex="-1">CSWSH 跨站 WebSocket 劫持 <a class="header-anchor" href="#cswsh-跨站-websocket-劫持" aria-label="Permalink to &quot;CSWSH 跨站 WebSocket 劫持&quot;">​</a></h2><p>黑客把恶意脚本放进钓鱼网页，受害者一旦访问，浏览器就<strong>自动</strong>向真网站发起 WebSocket 连接并带上登录 Cookie——而 WebSocket 不受同源策略（CORS）约束。防线在于：浏览器会自动带 <code>Origin</code> 头，<strong>校验与拒绝的权力在服务端</strong>（RFC 6455 §10.2）。</p><h2 id="六道防线-全部实测通过" tabindex="-1">六道防线（全部实测通过） <a class="header-anchor" href="#六道防线-全部实测通过" aria-label="Permalink to &quot;六道防线（全部实测通过）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>防线</th><th>拦截结果</th></tr></thead><tbody><tr><td>1</td><td>Origin 白名单（<code>verifyClient</code>）</td><td>握手失败 HTTP 401</td></tr><tr><td>2</td><td>Token 鉴权（握手 URL 校验）</td><td>握手失败 HTTP 401</td></tr><tr><td>3</td><td><code>maxPayload: 4KB</code> 消息上限</td><td>自动关闭 1009</td></tr><tr><td>4</td><td>单 IP 最多 3 条连接</td><td>关闭 1013</td></tr><tr><td>5</td><td>滑动窗口 1s ≤ 5 条消息</td><td>关闭 1013</td></tr><tr><td>6</td><td>JSON try-catch + <code>text</code> 1~500 字符白名单</td><td>回 error 不断连</td></tr></tbody></table><p>运行 <code>npm run secure-server</code> 与 <code>npm run security-test</code> 可复现：合法回显 ✅、伪造 Origin 401 ✅、坏 token 401 ✅、5KB 大包 1009 ✅、7 条连发 1013 ✅、非法 JSON 回提示 ✅。</p><h2 id="三个最常见的认知误区" tabindex="-1">三个最常见的认知误区 <a class="header-anchor" href="#三个最常见的认知误区" aria-label="Permalink to &quot;三个最常见的认知误区&quot;">​</a></h2><ol><li><strong>掩码 ≠ 加密</strong>：掩码密钥明文放在帧头，防的是中间代理被字节流欺骗（§10.3），任何中间人都能解开</li><li><strong>握手成功 ≠ 已登录</strong>：<code>Sec-WebSocket-Accept</code> 只证明对方懂协议（§10.8），不是身份认证</li><li><strong>非浏览器客户端不守规矩</strong>：curl/脚本能伪造任意 Origin 和头部，Origin 之外必须再做 Token 鉴权（§10.1）</li></ol><p>机密性与完整性只能靠 <strong>wss（TLS）</strong>，且 HTTPS 页面不允许连接明文 <code>ws://</code>（混合内容限制）。</p><hr><p>上一幕：<a href="./06-heartbeat-reconnect">第六幕</a> ｜ 下一幕：<a href="./08-job-map">第八幕 · WebSocket 职业图谱</a></p>',13)])])}const S=r(c,[["render",s]]);export{m as __pageData,S as default};
